package dev.pocketengine.features.teams;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

public final class TeamExecutionTreeTest {
    private JSONObject plan()throws Exception{return new JSONObject().put("teamRunId","team").put("planId","plan").put("revision",3).put("items",new JSONArray().put(new JSONObject().put("workItemId","item").put("title","真正工作项").put("memberId","a").put("assignmentId","child").put("itemRevision",2).put("ownerGeneration",4).put("status","completed")));}
    private JSONObject child(boolean delivered)throws Exception{return new JSONObject().put("assignmentId","child").put("taskId","child").put("runId","actual-run").put("taskStatus","completed").put("recordedFinalDelivery",delivered).put("totalOperations",30).put("operations",new JSONArray().put(TeamExecutionTree.operation("item","child","op","old-run","project_execute","receipt",123)));}
    @Test public void contributedIsNotFinalAndNativeIntentTimeNeverCreatesDuration()throws Exception{JSONObject tree=TeamExecutionTree.project(plan(),new JSONArray().put(child(false)),16),node=tree.getJSONArray("roots").getJSONObject(0),op=node.getJSONArray("children").getJSONObject(0);assertEquals("contributed",node.getString("state"));assertTrue(tree.getBoolean("partial"));assertTrue(node.isNull("durationMillis"));assertEquals("item",op.getString("parentId"));assertEquals("child",op.getString("taskId"));assertEquals("old-run",op.getString("runId"));assertEquals(123,op.getLong("preparedAt"));assertTrue(op.isNull("startedAt"));assertTrue(op.isNull("finishedAt"));assertTrue(op.isNull("durationMillis"));assertEquals("settled",op.getString("state"));for(JSONObject safe:new JSONObject[]{tree,node,op}){assertFalse(safe.has("arguments"));assertFalse(safe.has("receipt"));}assertEquals("receipt",op.getString("nativeState"));}
    @Test public void recordedFinalNativeProofAndUnknownOperationRemainDistinct()throws Exception{JSONObject row=child(true);row.put("totalOperations",1);JSONObject tree=TeamExecutionTree.project(plan(),new JSONArray().put(row),16);assertFalse(tree.getBoolean("partial"));assertEquals("recorded_delivered",tree.getJSONArray("roots").getJSONObject(0).getString("state"));row.put("operations",new JSONArray().put(TeamExecutionTree.operation("item","child","op","run","team_write_file","unknown",5)));JSONObject pending=TeamExecutionTree.project(plan(),new JSONArray().put(row),16);assertEquals("awaiting_reconciliation",pending.getJSONArray("roots").getJSONObject(0).getString("state"));assertEquals("awaiting_reconciliation",pending.getJSONArray("roots").getJSONObject(0).getJSONArray("children").getJSONObject(0).getString("state"));assertFalse(tree.getBoolean("executionAuthorized"));assertFalse(tree.getBoolean("businessVerified"));}
}
